using FluentValidation;namespace Namaa.Application.Quotations.Commands.AddQuotationItem;public sealed class AddQuotationItemCommandValidator:AbstractValidator<AddQuotationItemCommand>{public AddQuotationItemCommandValidator(){RuleFor(x=>x.QuotationId).GreaterThan(0);RuleFor(x=>x.Description).NotEmpty().MaximumLength(500);RuleFor(x=>x.Quantity).GreaterThan(0);RuleFor(x=>x.UnitPrice).GreaterThanOrEqualTo(0);RuleFor(x=>x.DiscountAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.TaxAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.ServiceId).GreaterThan(0).When(x=>x.ServiceId.HasValue);}}

